__NUXT_JSONP__("/", (function(a,b,c,d){return {data:[{$axios:{request:{},getUri:{},delete:{},get:{},head:{},options:{},post:{},put:{},patch:{},defaults:{headers:{common:{Accept:"application\u002Fjson, text\u002Fplain, *\u002F*","accept-encoding":"gzip, deflate"},delete:{},get:{},head:{},post:{"Content-Type":"application\u002Fx-www-form-urlencoded"},put:{"Content-Type":"application\u002Fx-www-form-urlencoded"},patch:{"Content-Type":"application\u002Fx-www-form-urlencoded"}},baseURL:"http:\u002F\u002Flocalhost:8000",transformRequest:[{}],transformResponse:[{}],timeout:0,adapter:{},xsrfCookieName:"XSRF-TOKEN",xsrfHeaderName:"X-XSRF-TOKEN",maxContentLength:-1,maxBodyLength:-1,validateStatus:{},transitional:{silentJSONParsing:true,forcedJSONParsing:true,clarifyTimeoutError:false}},interceptors:{request:{handlers:[{fulfilled:{},rejected:void 0,synchronous:false,runWhen:null}]},response:{handlers:[]}},CancelToken:{source:{}},isCancel:{},setBaseURL:{},setHeader:{},setToken:{},onRequest:{},onResponse:{},onRequestError:{},onResponseError:{},onError:{},create:{},$request:{},$delete:{},$get:{},$head:{},$options:{},$post:{},$put:{},$patch:{}},details:{slug:"en",pageTitle:a,pageDescription:a,peopleChooseMli:{title:"3 Reasons People Choose MLI (STAGING)",subtitle:"(Mentor Language Institute)",lists:[{image:"\u002Fimages\u002Fhome\u002Fen\u002Fpeople-choose-mli-1.jpg",title:"Hollywood & Westwood",description:"We are located in great, popular areas of Los Angeles. Students can not only study English, but also enjoy Los Angeles.",read_more:[b]},{image:"\u002Fimages\u002Fhome\u002Fen\u002Fpeople-choose-mli-2.jpg",title:"Morning, Afternoon and Evening classes",description:"We provide Morning, Afternoon and Evening classes for people who need flexible schedules.",read_more:["\u003Ca href=\"\u002Ffeature\u002F\"\u003E» Read More » \u003C\u002Fa\u003E"]},{image:"\u002Fimages\u002Fhome\u002Fen\u002Fpeople-choose-mli-3.jpg",title:"$201 \u002F 1 week ～",description:"Good Location and Reasonable Price! Please compare our prices to other schools. If you want tuition information, click on Contact Us below.",read_more:[b]}]},highlyRated:"\u002Fimages\u002Fhome\u002Fen\u002Fmli-highly-rated.jpg",courses:{title:"Courses",lists:[{image:c,title:"ESL Program",subtitle:["This program is composed of listening\u002Fspeaking, reading\u002Fvocabulary, and grammar\u002Fwriting classes. The ESL program is ideal for students who want to improve their general English skills."]},{image:d,title:"TOEFL® Program",subtitle:["MLI’s TOEFL® program is an intensive look at the skills and strategies necessary to achieve a successful score on the four sections of the Internet-Based Test (iBT)."]},{image:c,title:"Vacation ESL program",subtitle:["This program is composed of listening\u002Fspeaking, reading\u002Fvocabulary, and grammar\u002Fwriting classes.  \u003Cbr\u003EWe offer the Vacation ESL program for students who want to study English for a short term."]},{image:d,title:"IELTS™ Program",subtitle:["IELTS™ is a test, developed in the UK and Australia, to evaluate students' English proficiency. Recently, many American universities require either a TOEFL® score, or an IELTS™ score.","The program consists of four parts: listening, speaking, reading and writing. In this class, you will learn the skills\u002Fstrategies for achieving high scores in each section.","IELTS™ is said to be relatively easier than TOEFL®. It is a perfect program for students who find TOEFL® difficult."]},{image:"\u002Fimages\u002Ficons\u002Fmessage.png",title:"Conversation Program",subtitle:["Our program focuses on enhancing your conversational skills in English through engaging activities and interactive learning! In our conversation classes, students will explore a wide range of vocabulary, phrases, and idioms that will make your conversations come alive. Practice your pronunciation in our CMAR class. Through fun discussions, role-plays, and group activities, you'll gain confidence in expressing yourself and engaging in meaningful conversations. Our experienced instructors provide a supportive learning environment, guiding you on a journey of language discovery. "]},{image:"\u002Fimages\u002Ficons\u002Fsuitcase.png",title:"Business plus TOEIC® Program",subtitle:["The TOEIC® test is an indicator of English proficiency in business and is used by various companies and organizations around the world. In addition to the standard Business program, the TOEIC® program prepares students for success on the TOEIC® - Listening and Reading Exam by introducing essential vocabulary and exploring strategies for achieving a high score on the test.","This program will be helpful in improving your English skills, such as vocabulary, reading, listening, and grammar. By learning the strategies to find correct answers, you will be able to get a high score."]}]},schedule:"\u002Fimages\u002Fhome\u002Fen\u002Ffree_trial_banner-En.png",link:"\u002Ffreetrial",partnerSchools:{title:"MLI's Partner Universities \u002F Colleges",subtitle:"\"MLI students can enroll at partner universities or colleges after completing certain MLI programs.\""},locationCampus:{title:"Location \u002F Campus",lists:[{image:"\u002Fimages\u002Fhome\u002Flocation-campus-1.jpg",title:"Westwood Campus",subtitle:"Westwood is a vibrant, unique neighborhood located on the west side of Los Angeles. Westwood is famous for being the home of UCLA. It is a very fun and popular area for students since there are a lot of university students and many shops, restaurants and safe places to hang out.",read_more:["\u003Ca href=\"\u002Fwestwood\u002F\"\u003E» Read More\u003C\u002Fa\u003E"]},{image:"\u002Fimages\u002Fhome\u002Flocation-campus-2.jpg",title:"Hollywood Campus",subtitle:"The Hollywood campus is right next to the famous Chinese Theater. There are famous movie theaters, good restaurants, shops and clubs in the Hollywood area. This area is always very livery.",read_more:["\u003Ca href=\"\u002Fhollywood\u002F\"\u003E» Read More\u003C\u002Fa\u003E"]}]},testimonials:{title:"Student Testimonials",seemoreBtn:"See more Testimonials",TestimonialLink:"\u002Ftestimonials",readmoreBtn:"Read More"},dir:"\u002Fhome",path:"\u002Fhome\u002Fen",extension:".json",createdAt:"2026-10-22T16:31:29.594Z",updatedAt:"2026-11-24T15:20:04.483Z"}}],fetch:{},mutations:void 0}}("Affordable English School in Los Angeles | Mentor Language Institute","\u003Ca href=\"\u002Ffeature\u002F\"\u003E» Read More\u003C\u002Fa\u003E","\u002Fimages\u002Ficons\u002Fpaste.png","\u002Fimages\u002Ficons\u002Fpen.png")));